parameters.jsCode:
const body = $json.body || $json;
const data = body.data || {};
const message = data.message || {};

const msg = (
  message.conversation ||
  message.extendedTextMessage?.text ||
  message.imageMessage?.caption ||
  message.videoMessage?.caption ||
  message.documentMessage?.caption ||
  ''
).toString().trim();

const remoteJid = (
  data.key?.remoteJid ||
  body.sender ||
  'unknown'
).toString().trim();

const phone = remoteJid.replace(/@.*/, '').replace(/\D/g, '');

const lowerMsg = msg.toLowerCase();

const intents = {
  human: /human|person|agent|support|help me|talk to|speak to|representative/.test(lowerMsg),
  book: /book|schedule|appointment|calendar|demo|call|meeting|slot/.test(lowerMsg),
  pricing: /price|pricing|cost|how much|budget|quote|fee/.test(lowerMsg),
  returning: /continue|pick up|where we left|last time|again/.test(lowerMsg)
};

const variants = [
  "Hey! I'm Ava from FlowForge. What tedious task is eating up your team's time?",
  "Hi there! I help businesses automate their busywork at FlowForge. What's your biggest time waster right now?",
  "Hello! Curious - how many hours does your team spend on manual data entry each week?"
];
const variantIndex = Math.floor(Math.random() * variants.length);

// Restart ONLY on explicit commands - NOT greetings
const restart = /^(restart|reset|start over|start again)(\s|[!.])*$/i.test(msg);

const tzMap = {
  '+1': 'America/New_York', '+44': 'Europe/London', '+234': 'Africa/Lagos',
  '+49': 'Europe/Berlin', '+91': 'Asia/Kolkata', '+61': 'Australia/Sydney',
  '+33': 'Europe/Paris', '+39': 'Europe/Rome', '+34': 'Europe/Madrid',
  '+971': 'Asia/Dubai', '+27': 'Africa/Johannesburg', '+55': 'America/Sao_Paulo'
};
let timezone = 'Africa/Lagos';
const phoneWithPlus = phone.startsWith('+') ? phone : '+' + phone;
for (const [prefix, tz] of Object.entries(tzMap)) {
  if (phoneWithPlus.startsWith(prefix)) { timezone = tz; break; }
}

return [{
  json: {
    original_message: msg,
    phone: phone,
    remote_jid: remoteJid,
    intent: intents,
    greeting_variant: variants[variantIndex],
    variant_index: variantIndex,
    timezone: timezone,
    timestamp: new Date().toISOString(),
    restart: restart
  }
}];

const meta = $('Detect Intent & Metadata').first().json;
const history = $json.messages || [];
const hasMemory = history.length > 0;

let handoffTime = null;

// Search history for the system handoff timestamp (newest first)
for (let i = history.length - 1; i >= 0; i--) {
  const msg = history[i];
  let msgText = '';

  if (msg.system) {
    msgText = typeof msg.system === 'string' ? msg.system : (msg.system.text || msg.system.content || '');
  } else if (msg.content) {
    msgText = typeof msg.content === 'string' ? msg.content : (msg.content.text || msg.content.content || '');
  } else if (msg.text) {
    msgText = typeof msg.text === 'string' ? msg.text : '';
  }

  const match = msgText.match(/SYSTEM HANDED OFF BY (.+)/i);
  if (match && match[1]) {
    const parsed = new Date(match[1].trim());
    if (!isNaN(parsed.getTime())) {
      handoffTime = parsed;
      break;
    }
  }
}

// Fallback: detect handoff language in recent AI messages
let handedOffLegacy = false;
if (!handoffTime) {
  for (let i = history.length - 1; i >= Math.max(0, history.length - 8); i--) {
    let aiRaw = history[i].ai;
    if (typeof aiRaw === 'object' && aiRaw !== null) aiRaw = aiRaw.text || aiRaw.content || '';
    if (typeof aiRaw !== 'string') aiRaw = '';
    const aiMsg = aiRaw.toLowerCase();
    if (aiMsg.includes('connecting you with oyekola') ||
        aiMsg.includes("you'll hear back within 10 minutes") ||
        aiMsg.includes('has been handed off')) {
      handedOffLegacy = true;
      break;
    }
  }
}

// Check if handoff is still within the 10-minute window
let isHandoffActive = false;
const now = new Date();

if (handoffTime) {
  const elapsedMs = now.getTime() - handoffTime.getTime();
  const tenMinutesMs = 10 * 60 * 1000;
  isHandoffActive = elapsedMs < tenMinutesMs;
} else if (handedOffLegacy) {
  isHandoffActive = true;
}

return [{
  json: {
    is_handoff_active: isHandoffActive,
    has_memory: hasMemory,
    phone: meta.phone,
    remote_jid: meta.remote_jid,
    original_message: meta.original_message
  }
}];

// Parse raw chat history from memory
const history = $json.messages || [];
const meta = $('Detect Intent & Metadata').first().json;

// Helper to safely get string from various message formats
function getText(raw) {
  if (typeof raw === 'string') return raw;
  if (typeof raw === 'object' && raw !== null) {
    return raw.text || raw.content || JSON.stringify(raw);
  }
  return '';
}

// Extract clean conversation (strip the bloated system prompts)
const chat = [];
for (const turn of history) {
  const humanFull = getText(turn.human);
  const match = humanFull.match(/The user's current message is:\s*(.*?)(?:\n|CONTEXT PROVIDED)/s);
  const userMsg = match ? match[1].trim() : '';
  const aiMsg = getText(turn.ai).trim();

  if (userMsg && !userMsg.match(/^You are "Ava"/)) {
    chat.push({ sender: 'Lead', text: userMsg });
  }
  if (aiMsg) {
    chat.push({ sender: 'Ava', text: aiMsg });
  }
}

// Pull out user messages only for extraction
const userTexts = chat.filter(t => t.sender === 'Lead').map(t => t.text);
const combined = userTexts.join(' ');

// Extract lead intel
let name = '';
let company = '';
let email = '';
let budget = '';
let interest = '';
let pain = '';

const nameMatch = combined.match(/my name is ([A-Za-z\s'’-]+?)(?:\s+and|\s+from|\s*$)/i);
if (nameMatch) name = nameMatch[1].trim();

const companyMatch = combined.match(/work for ([\w\s&]+?)(?:\.|\?|$)/i) || 
                     combined.match(/company (?:is|name) ([\w\s&]+?)(?:\.|\?|$)/i) ||
                     combined.match(/from ([\w\s&]+?)(?:\.|\?|$)/i);
if (companyMatch) company = companyMatch[1].trim();

const emailMatch = combined.match(/([\w.-]+@[\w.-]+\.\w+)/);
if (emailMatch) email = emailMatch[1];

const budgetMatch = combined.match(/(\$\d[\dk\+]+|\d[\dk\+]*\s*(?:naira|usd|dollars?|k))/i);
if (budgetMatch) budget = budgetMatch[1];

// Detect interest from conversation
const fullText = combined.toLowerCase();
if (/chatbot|customer support|inquiry|response|answering customers/i.test(fullText)) {
  interest = 'AI Chatbots & Agents';
}
else if (/workflow|automation|manual|data entry|repetitive/i.test(fullText)) {
  interest = 'Workflow Automation';
}
else if (/document|invoice|contract|form|pdf/i.test(fullText)) {
  interest = 'Document Intelligence';
}
else if (/crm|lead|pipeline|follow-up|follow up/i.test(fullText)) {
  interest = 'CRM & Lead Management';
}
else if (/custom|gpt|claude|voice|integration|api/i.test(fullText)) {
  interest = 'Custom AI Integrations';
}

// Pain point = first substantive user message (skip greetings)
const interestPain = userTexts.find(t => /chatbot|customer|inquiry|support|answering/i.test(t));
const firstRealMsg = userTexts.find(t => !t.match(/^(hey|hi|hello|yo|what'?s up)/i));
pain = interestPain || firstRealMsg || '';

// Build one-line summary bullets
const bullets = [];
if (pain) bullets.push(`Pain: "${pain}"`);
if (interest) bullets.push(`Interest: ${interest}`);
if (name) bullets.push(`Name: ${name}`);
if (company) bullets.push(`Company: ${company}`);
if (email) bullets.push(`Email: ${email}`);
if (budget) bullets.push(`Budget: ${budget}`);

const summary = bullets.length > 0 ? bullets.join(' | ') : 'Early-stage conversation';

return [{
  json: {
    handoff_name: name || 'Not provided',
    handoff_company: company || 'Not provided',
    handoff_email: email || 'Not provided',
    handoff_budget: budget || 'Not provided',
    handoff_interest: interest || 'Not determined',
    handoff_pain: pain || 'Not specified',
    handoff_summary: summary,
    handoff_turns: userTexts.length,
    phone: meta.phone,
    last_message: meta.original_message,
    remote_jid: meta.remote_jid
  }
}];

