return [{
  json: {
    text: $json.original_message,
    phone: $json.phone,
    remote_jid: $json.remote_jid,
    timezone: $json.timezone,
    greeting_variant: $json.greeting_variant,
    variant_index: $json.variant_index,
    intent: $json.intent,
    timestamp: $json.timestamp,
    has_memory: $json.has_memory || false
  }
}];

const output = ($json.output || $json.text || $json.response || '').toString();
const hasMarker = output.includes('[LEAD_SAVED]');
const cleanText = output.replace(/\[LEAD_SAVED\]/g, '').trim();
return [{
  json: {
    clean_text: cleanText,
    has_marker: hasMarker,
    phone: $json.phone,
    remote_jid: $json.remote_jid,
    original_output: output
  }
}];

